/// <summary>
/// Base class contains the logic to implement payment controls on the payment journals
/// </summary>
public class METPaymentControl
{
    ErrorMessage            errorMessage;
    LedgerJournalACType     accountType;
    PaymMode                paymMode;
    METRecordAction         action;
    CustVendPaymStatus      paymStatus;
    CustVendPaymStatus      paymStatusTo;

    METPaymentControlTable      metPaymentControlTable;
    LedgerJournalTrans          ledgerJournalTrans;

}

Method.Source:
    /// <summary>
    /// Construct <c>METPaymentControl</c> instance
    /// </summary>
    /// <param name = "_accountType">AccountType</param>
    /// <param name = "_paymMode">Payment mode</param>
    /// <param name = "_paymStatus">Payment status</param>
    /// <param name = "_action">Update/Delete</param>
    /// <param name = "_paymStatusTo">Payment status to be updated to</param>
    /// <returns><c>METPaymentControl</c> class instance</returns>
    public static METPaymentControl construct(LedgerJournalACType   _accountType,
                                              PaymMode              _paymMode,
                                              CustVendPaymStatus    _paymStatus,
                                              METRecordAction       _action,
                                              CustVendPaymStatus    _paymStatusTo = CustVendPaymStatus::None)
    {
        METPaymentControl       paymentControl = new METPaymentControl();

        paymentControl.initParms(_accountType, _paymMode, _paymStatus, _action, _paymStatusTo);

        return paymentControl;
    }

    /// <summary>
    /// Construct <c>METPaymentControl</c> instance
    /// </summary>
    /// <param name = "_ledgerJournalTrans">LedgerJournalTrans buffer.</param>
    /// <param name = "_action">Update/delete</param>
    /// <param name = "_statusTo">Status to be updated to</param>
    /// <returns><c>METPaymentControl</c> class instance</returns>
    public static METPaymentControl newFromledgerJournalTrans(LedgerJournalTrans    _ledgerJournalTrans,
                                                              METRecordAction       _action,
                                                              CustVendPaymStatus    _statusTo = CustVendPaymStatus::None)
    {
        METPaymentControl       paymentControl = new METPaymentControl();

        paymentControl.parmLedgerJournalTrans(_ledgerJournalTrans);
        paymentControl.initParms(_ledgerJournalTrans.AccountType, 
                                _ledgerJournalTrans.PaymMode,
                                _ledgerJournalTrans.PaymentStatus,
                                _action,
                                _statusTo);
        return paymentControl;
    }

/// <summary>
/// Initialise parameters
/// </summary>
/// <param name = "_accountType">AccountType</param>
/// <param name = "_paymMode">Payment mode</param>
/// <param name = "_paymStatus">Payment status</param>
/// <param name = "_action">Update/Delete</param>
/// <param name = "_paymStatusTo">Payment status to be updated to</param>
public void initParms(LedgerJournalACType  _accountType,
                    PaymMode              _paymMode,
                    CustVendPaymStatus    _paymStatus,
                    METRecordAction       _action,
                    CustVendPaymStatus    _paymStatusTo)
{
    this.parmAccountType(_accountType);
    this.parmPaymMode(_paymMode);
    this.parmPaymStatus(_paymStatus);
    this.parmPaymStatusTo(_paymStatusTo);
    this.parmAction(_action);
}

    /// <summary>
    /// This method executes the logic to validate the update or delete action against the payment line payment status.
    /// </summary>
    /// <returns>True if action is allowed; otherwise false</returns>
    public boolean validateAction()
    {
        boolean                     ret;

        //Check before validating the payment status
        if (!ledgerJournalTrans.metValidatePaymentStatus())
        {
            return true;
        }

        switch (action)
        {
            case METRecordAction::Update:
                ret = this.validateUpdate();
                break;
            case METRecordAction::Delete:
                ret = this.validateDelete();
                break;
            default:
                ret = true;
        }

        return ret;
    }

    private boolean validateUpdate()
    {
        select RecId from metPaymentControlTable
            where metPaymentControlTable.AccountType == accountType
            && metPaymentControlTable.PaymMode == paymMode
            && metPaymentControlTable.PaymentStatus == paymStatus
            && metPaymentControlTable.UpdateToStatus == paymStatusTo
            && (action == METRecordAction::Update && metPaymentControlTable.AllowUpdate);

        if (action == METRecordAction::Update && !metPaymentControlTable.RecId)
        {
            return checkFailed("@MET:PaymentStatusUpdateWarning");
        }

        return true;
    }

    /// <summary>
    /// Find and validate delete action of the payment status.
    /// </summary>
    /// <returns>True if record can be deleted; otherwise false</returns>
    private boolean validateDelete()
    {
        select RecId from metPaymentControlTable
            where metPaymentControlTable.AccountType == accountType
            && metPaymentControlTable.PaymMode == paymMode
            && metPaymentControlTable.PaymentStatus == paymStatus
            && (action == METRecordAction::Delete && metPaymentControlTable.AllowDelete);

        if (action == METRecordAction::Delete && !metPaymentControlTable.RecId)
        {
            return checkFailed("@MET:PaymentStatusDeleteWarning");
        }

        return true;
    }

/// <summary>
/// LedgerJournalTrans buffer
/// </summary>
/// <param name = "_ledgerJournalTrans">LedgerJournalACType</param>
/// <returns>LedgerJournalTrans</returns>
public LedgerJournalTrans parmLedgerJournalTrans(LedgerJournalTrans _ledgerJournalTrans = ledgerJournalTrans)
{
    ledgerJournalTrans =   _ledgerJournalTrans;
    return ledgerJournalTrans;
}

/// <summary>
/// Account type parameter
/// </summary>
/// <param name = "_accountType">LedgerJournalACType</param>
/// <returns>LedgerJournalACType</returns>
public LedgerJournalACType parmAccountType(LedgerJournalACType _accountType = accountType)
{
    accountType =   _accountType;
    return accountType;
}

/// <summary>
/// Payment mode parameter
/// </summary>
/// <param name = "_paymMode">PaymMode</param>
/// <returns>PaymMode</returns>
public PaymMode parmPaymMode(PaymMode _paymMode = paymMode)
{
    paymMode =   _paymMode;
    return PaymMode;
}

/// <summary>
/// Update/Delete action 
/// </summary>
/// <param name = "_action">AxdRecordAction</param>
/// <returns>AxdRecordAction</returns>
public METRecordAction parmAction(METRecordAction _action = action)
{
    action =   _action;
    return action;
}

/// <summary>
/// Payment status to update
/// </summary>
/// <param name = "_paymStatus">CustVendPaymStatus</param>
/// <returns>CustVendPaymStatus</returns>
public CustVendPaymStatus parmPaymStatus(CustVendPaymStatus _paymStatus = paymStatus)
{
    paymStatus =   _paymStatus;
    return paymStatus;
}

/// <summary>
/// Payment status to be updated to
/// </summary>
/// <param name = "_paymStatusTo">CustVendPaymStatus</param>
/// <returns>CustVendPaymStatus</returns>
public CustVendPaymStatus parmPaymStatusTo(CustVendPaymStatus _paymStatusTo = paymStatusTo)
{
    paymStatusTo =   _paymStatusTo;
    return paymStatusTo;
}
